	if err != nil {
		return nil, err
	}
	lsResp := make(map[int64]Livestream, len(lss))
	for _, l := range lss {
		lsResp[l.ID] = l
	}
	users, err := fillUsers(ctx, db, userIDs)
	if err != nil {
		return nil, err
	}
	res := make([]Reaction, len(models))
	for i, m := range models {
		res[i] = Reaction{
			ID:         m.ID,
			EmojiName:  m.EmojiName,
			User:       users[m.UserID],
			Livestream: lsResp[m.LivestreamID],
			CreatedAt:  m.CreatedAt,
		}
	}
	return res, nil
}

