// likeContainsCI emulates `text COLLATE utf8mb4_general_ci LIKE CONCAT('%', word, '%')`.
// ok=false means the result is uncertain and SQL should be used.
func likeContainsCI(text, word string) (match bool, ok bool) {
	if strings.ContainsAny(word, "%_\\") {
		return false, false
	}
	if !simpleRunes(text) || !simpleRunes(word) {
		return false, false
	}
	return strings.Contains(asciiLower(text), asciiLower(word)), true
}

func simpleRunes(s string) bool {
	for _, r := range s {
		if r >= 0x80 && r < 0x3000 {
			return false
		}
		if r >= 0xFF00 && r <= 0xFFEF {
			return false
		}
		if r >= 0xD800 && r <= 0xDFFF || r == 0xFFFD {
			return false
		}
	}
	return true
}

func asciiLower(s string) string {
	hasUpper := false
	for i := 0; i < len(s); i++ {
		if s[i] >= 'A' && s[i] <= 'Z' {
			hasUpper = true
			break
		}
	}
	if !hasUpper {
		return s
	}
	b := []byte(s)
	for i := range b {
		if b[i] >= 'A' && b[i] <= 'Z' {
			b[i] += 'a' - 'A'
		}
	}
	return string(b)
}

// storeSpamCheck returns (hit, certain).
func storeSpamCheck(lsID, ownerID int64, comment string) (bool, bool) {
	storeMu.RLock()
	defer storeMu.RUnlock()
	certain := true
	for _, w := range ngwordsByLS[lsID] {
		if w.UserID != ownerID {
			continue
		}
		m, ok := likeContainsCI(comment, w.Word)
		if !ok {
			certain = false
			continue
		}
		if m {
			return true, true
		}
	}
	return false, certain
}
EOF
