def simple(s, isword=False):
    for ch in s:
        r=ord(ch)
        if unsure_r(r): return False
        if isword and r>0xFFFF: return False
    return True
def low(s): return ''.join(c.lower() if 'A'<=c<='Z' else c for c in s)
lc=[(cid,low(c),simple(c)) for cid,c in coms]
mine=set(); unsure=0; unsure_c=sum(1 for x in lc if not x[2])
for wid,w in words:
    if any(c in w for c in '%_\\') or not simple(w,True): unsure+=1; continue
    lw=low(w)
    for cid,c,s in lc:
        if s and lw in c: mine.add((wid,cid))
